//! SkillEvaluator parity with the Python adapter over hostile inputs (tests/fixtures/skillevaluator/se_golden.json,
//! generated by the Python adapter with gen_se_golden.py): summarize_tier1 / failed_checks / summarize_tier3 /
//! last_json_object, and the report text of stored runs with odd run.json values (or the exception it raises).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

#[path = "skillevaluator_helpers.rs"]
mod helpers;

use helpers::*;
use nemo_console::adapters::base::SystemAdapter;
use nemo_console::adapters::skillevaluator::{
    failed_checks, last_json_object, summarize_tier1, summarize_tier3,
};
use serde_json::{Value, json};

fn golden() -> Value {
    let p = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/skillevaluator/se_golden.json"
    );
    serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap()
}

#[test]
fn test_report_parsing_matches_the_python_adapter() {
    let g = golden();
    let mut failures = Vec::new();
    let mut checked = 0;
    for c in g["summaries"].as_array().unwrap() {
        let (got, want) = match c["kind"].as_str().unwrap() {
            "last_json" => (
                last_json_object(c["input"].as_str().unwrap()).map_or(Value::Null, Value::Object),
                c["summary"].clone(),
            ),
            kind => {
                // the adapter only ever passes a dict (its loaders return a JSON object or nothing)
                let Some(d) = c["input"].as_object() else {
                    continue;
                };
                if kind == "tier1" {
                    let got =
                        json!({"summary": summarize_tier1(d), "failed": failed_checks(d, 12)});
                    (got, json!({"summary": c["summary"], "failed": c["failed"]}))
                } else {
                    (Value::Object(summarize_tier3(d)), c["summary"].clone())
                }
            }
        };
        checked += 1;
        if got != want {
            failures.push(format!(
                "{}: {}\n  want {want}\n  got  {got}",
                c["kind"], c["input"]
            ));
        }
    }
    assert!(checked > 100);
    assert!(
        failures.is_empty(),
        "{} differences:\n{}",
        failures.len(),
        failures
            .iter()
            .take(8)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}

#[tokio::test]
async fn test_report_texts_match_the_python_adapter() {
    let g = golden();
    let reports = g["reports"].as_array().unwrap();
    assert!(reports.len() > 100);
    let t3 = fx("tier3_result.json");
    let mut failures = Vec::new();
    // one fixture for every case (each case has its own run id); the report path makes no upstream call
    let f = Fx::new().await;
    let a = f.adapter(&FakeRunner::new());
    let re = regex::Regex::new(r"(?i)(running for )\d+( min)").unwrap();
    for c in reports {
        let meta = &c["meta"];
        let run_id = meta["run_id"].as_str().unwrap();
        let run_dir = a.runs_dir().join(run_id);
        std::fs::create_dir_all(&run_dir).unwrap();
        std::fs::write(run_dir.join("run.json"), meta.to_string()).unwrap();
        if c["md"] == true {
            std::fs::write(
                run_dir.join("skillevaluator-tier1.md"),
                "# Report\n\n| a | b |\n",
            )
            .unwrap();
        }
        if c["tree"] == true {
            let rd = run_dir.join("calculator/20261017_091635_7_46d5ccd742f5");
            std::fs::create_dir_all(&rd).unwrap();
            std::fs::write(rd.join("result.json"), &t3).unwrap();
            std::fs::write(rd.join("report.html"), "<html></html>\n").unwrap();
        }
        let got = match a
            .run_action("report", &params(json!({"run_id": run_id})))
            .await
        {
            Ok(r) => {
                json!({"ok": r.ok, "output": r.output.replace(run_dir.to_str().unwrap(), "<RUN_DIR>")})
            }
            Err(e) => json!({"raised": {"class": e.py_class(), "message": e.to_string()}}),
        };
        let mut want = c["report"].clone();
        // `running for N min` depends on the clock: the stored ts is the same, the minutes differ by the age of
        // the golden; normalise only that number
        let norm = |v: &mut Value| {
            if let Some(Value::String(s)) = v.get_mut("output") {
                *s = re.replace_all(s, "${1}N${2}").into_owned();
            }
        };
        let mut got = got;
        norm(&mut got);
        norm(&mut want);
        if got != want {
            failures.push(format!("meta {meta}\n  want {want}\n  got  {got}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} differences:\n{}",
        failures.len(),
        failures
            .iter()
            .take(6)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}
